/*
 * ANSWERING A CHECK-IN (DBU-10). Only her own shared check-in, only once it has gone out, only once.
 * The answers are checked against the STEP'S copy of the form, in question order:
 *  - a question shows only when its condition holds on the answers above it (the Hub's SurveyForm
 *    rules: {field, value | [values]}, {field, not}, {field, operator, value}); the answer to a
 *    hidden one is dropped. Checkin/Question applies the same rules on the page: change both.
 *  - scale: a whole number min..max · number: min..max, a comma reads as a point · text up to 500
 *    characters, textarea up to 5,000 · radio: one option's value · checkbox: some options' values.
 *  - required and shown, it must be answered. An empty answer is no answer.
 * Saved as one CheckinResponse with its own copy of the form, so an answer always has its questions.
 * The step is done. Rings her plan doorbell and the staff's inbox bell.
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const R = Noodl.Records;
    const me = String(Inputs.userId || '');
    if (!me) throw new Error('no session user');
    const q = (c, where) => R.query(c, where, { limit: 2, plain: true });
    const id = String(Inputs.stepId || '');
    const steps = id ? await q('Step', { objectId: { equalTo: id } }) : [];
    const s = steps[0];
    if (!s || s.learner !== me || s.shared !== true || s.kind !== 'checkin') return refuse('This check-in could not be found. Open it from your Home page.');
    if (s.status === 'done' || (await q('CheckinResponse', { step: { equalTo: id } })).length) return refuse('You have already sent your answers to this check-in. Thank you!');
    if (s.status !== 'sent') return refuse('This check-in is not open yet. It arrives by email on the day it is due.');

    const given = Inputs.answers && typeof Inputs.answers === 'object' && !Array.isArray(Inputs.answers) ? Inputs.answers : {};
    const form = s.form && Array.isArray(s.form.questions) ? s.form : { questions: [] };
    const shown = (qn, sofar) => {
      const c = qn.condition;
      if (!c || !c.field) return true;
      const v = sofar[c.field];
      if (Array.isArray(c.value)) return c.value.includes(v);
      if (c.operator) {
        const n = Number(v);
        if (v === undefined || !Number.isFinite(n)) return false;
        if (c.operator === '>') return n > c.value;
        if (c.operator === '<') return n < c.value;
        if (c.operator === '>=') return n >= c.value;
        if (c.operator === '<=') return n <= c.value;
        return false;
      }
      if (c.not !== undefined) return v !== c.not;
      return v === c.value;
    };
    const clean = {};
    for (const qn of form.questions) {
      if (!qn || !qn.id || !shown(qn, clean)) continue;
      const label = '“' + String(qn.label || qn.id) + '”';
      const raw = given[qn.id];
      const values = (Array.isArray(qn.options) ? qn.options : []).map((o) => (o && typeof o === 'object' ? o.value : o));
      let v;
      if (raw === undefined || raw === null || (typeof raw === 'string' && !raw.trim()) || (Array.isArray(raw) && !raw.length)) v = undefined;
      else if (qn.type === 'scale') {
        const n = Number(raw);
        const lo = Number.isFinite(qn.min) ? qn.min : 1;
        const hi = Number.isFinite(qn.max) ? qn.max : 5;
        if (!Number.isInteger(n) || n < lo || n > hi) return refuse(label + ': pick a number from ' + lo + ' to ' + hi + '.');
        v = n;
      } else if (qn.type === 'number') {
        const n = Number(String(raw).trim().replace(',', '.'));
        if (!Number.isFinite(n)) return refuse(label + ': write a number, like 2 or 1.5.');
        if (Number.isFinite(qn.min) && n < qn.min) return refuse(label + ': write a number of at least ' + qn.min + '.');
        if (Number.isFinite(qn.max) && n > qn.max) return refuse(label + ': write a number up to ' + qn.max + '.');
        v = Math.round(n * 100) / 100;
      } else if (qn.type === 'radio') {
        if (!values.includes(raw)) return refuse(label + ': pick one of the answers offered.');
        v = raw;
      } else if (qn.type === 'checkbox') {
        const list = Array.isArray(raw) ? [...new Set(raw)] : [];
        if (!list.length || !list.every((x) => values.includes(x))) return refuse(label + ': tick the answers offered.');
        v = values.filter((x) => list.includes(x));
      } else {
        const t = String(raw).replace(/\r\n/g, '\n').trim();
        const max = qn.type === 'textarea' ? 5000 : 500;
        if (t.length > max) return refuse(label + ': keep it under ' + max.toLocaleString('en-GB') + ' characters.');
        v = t;
      }
      if (v === undefined) {
        if (qn.required === true) return refuse('Answer ' + label + ' before you send.');
        continue;
      }
      clean[qn.id] = v;
    }

    let row;
    try {
      row = await R.create('CheckinResponse', { step: id, learner: me, answers: clean, form }, { plain: true });
    } catch (e) {
      // The unique index on `step`: another press got there first.
      if ((await q('CheckinResponse', { step: { equalTo: id } })).length) return refuse('You have already sent your answers to this check-in. Thank you!');
      throw e;
    }
    await R.save(id, { status: 'done' }, { className: 'Step' });
    await R.create('Doorbell', { learner: me, topic: 'plan' }, { acl: { [me]: { read: true }, 'role:staff': { read: true } } });
    await R.create('Doorbell', { learner: me, topic: 'inbox' }, { acl: { 'role:staff': { read: true } } });
    Outputs.answeredAt = (row && row.createdAt) || new Date().toISOString();
    Outputs.done();
  } catch (e) {
    console.error('[dbu:answerCheckin]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
